using Microsoft.Extensions.DependencyInjection;
using ModelContextProtocol;

var builder = McpServerBuilder.ForStdioTransport();

// Register HttpClient via the DI container the MCP SDK exposes.
// IHttpClientFactory (and named/typed clients) become available
// to any tool class the SDK instantiates.
builder.Services.AddHttpClient("api", client =>
{
    client.BaseAddress = new Uri("https://jsonplaceholder.typicode.com");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

// WithTools<T>() tells the SDK to scan T for [McpServerTool] methods.
// The SDK will instantiate WeatherTools per-invocation via DI,
// injecting any constructor parameters registered above.
builder.WithTools<ApiTools>();

await using var server = builder.Build();
await server.RunAsync();

