using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tool class wrapping a REST API.
/// The SDK creates an instance per tool call, resolving constructor
/// parameters from the DI container automatically.
/// </summary>
public class ApiTools(IHttpClientFactory httpClientFactory)
{
    private readonly HttpClient _http = httpClientFactory.CreateClient("api");

    [McpServerTool(Name = "get_post",
        Description = "Gets a blog post by its numeric ID (1-100).")]
    public async Task<string> GetPost(
        [McpServerToolParameter(Description = "The post ID to retrieve (1-100).")]
        int id)
    {
        var post = await _http.GetFromJsonAsync<JsonElement>($"/posts/{id}");
        return JsonSerializer.Serialize(post, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerTool(Name = "list_posts",
        Description = "Lists blog posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [McpServerToolParameter(Description = "Optional user ID to filter posts.")]
        int? userId = null)
    {
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        var posts = await _http.GetFromJsonAsync<JsonElement>(url);
        return JsonSerializer.Serialize(posts, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerTool(Name = "get_comments",
        Description = "Gets all comments for a given post ID.")]
    public async Task<string> GetComments(
        [McpServerToolParameter(Description = "The post ID whose comments to retrieve.")]
        int postId)
    {
        var comments = await _http.GetFromJsonAsync<JsonElement>($"/posts/{postId}/comments");
        return JsonSerializer.Serialize(comments, new JsonSerializerOptions { WriteIndented = true });
    }
}

